// LLM'in çıktısını (bazen ```json ile sarılmış, bazen ham) güvenli şekilde JSON'a çevirir.
// Yorum analizi dalındaki parse-review-extraction.js ile aynı savunmacı mantık.

const rawText = $input.first().json.text || $input.first().json.output || "";

function guvenliJsonAyristir(text) {
  let temiz = text.trim();
  temiz = temiz.replace(/^```json\s*/i, "").replace(/^```\s*/, "").replace(/```\s*$/, "");
  temiz = temiz.trim();

  try {
    return JSON.parse(temiz);
  } catch (e) {
    const match = temiz.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (e2) {
        return null;
      }
    }
    return null;
  }
}

const parsed = guvenliJsonAyristir(rawText);

if (!parsed) {
  return [{
    json: {
      query: "",
      butce: 0,
      kategori: "",
      ayristirma_hatasi: true,
    }
  }];
}

return [{
  json: {
    query: parsed.query || "",
    butce: parsed.butce || 0,
    kategori: parsed.kategori || "",
    ayristirma_hatasi: false,
  }
}];

// HTTP Request'ten gelen ürün önerilerini kullanıcı dostu Markdown "kart" formatına çevirir
const response = $input.first().json;
const oneriler = response.oneriler || [];

if (oneriler.length === 0) {
  return [{
    json: {
      output: "😕 Aradığınız kriterlere uygun bir ürün bulamadım. Bütçenizi veya kategori tercihinizi değiştirmek ister misiniz?"
    }
  }];
}

const kategoriEmoji = {
  "Elektronik": "🔌", "Kadın": "👗", "Erkek": "👔", "Kozmetik": "💄",
  "Ayakkabı & Çanta": "👜", "Ev & Yaşam": "🏠", "Spor & Outdoor": "⚽",
  "Anne & Çocuk": "🧸", "Süpermarket": "🛒", "Saat & Aksesuar": "⌚"
};

const kartlar = oneriler.map((urun, index) => {
  // Kategori Erkek/Kadın gibi olsa bile alt kategori "Elektronik" ise elektronik emojisi kullan
  const emoji = urun.alt_kategori === "Elektronik"
    ? "🔌"
    : (kategoriEmoji[urun.ana_kategori] || "🛍️");
  const fiyatFormatli = urun.fiyat.toLocaleString('tr-TR', { minimumFractionDigits: 2 });
  const stokMetni = urun.stok_durumu === "STOKTA" ? "✅ Stokta" : "❌ Stokta yok";

  return `**${index + 1}. ${emoji} ${urun.urun_adi}**

- Marka: ${urun.marka}
- Fiyat: **${fiyatFormatli} TL**
- Puan: ⭐ ${urun.puan}/5 (${urun.yorum_sayisi} değerlendirme)
- Durum: ${stokMetni}
- Neden önerdim: ${urun.oneri_gerekcesi}`;
}).join("\n\n———————————————\n\n");

const baslik = `Size uygun ${oneriler.length} ürün buldum:\n\n`;

return [{
  json: {
    output: baslik + kartlar
  }
}];

// Kullanıcının "1", "3" gibi sıra numarası veya "Apple" gibi isim/marka belirtmesini
// gerçek ürün ID'sine çevirir. Redis'teki son öneri listesine bakar.
// EK: Kullanıcı bu mesajda ürün seçimini tekrar belirtmemişse (örn. sadece kritere
// cevap veriyorsa), Redis'teki "bekleyen karşılaştırma" kaydına bakarak hangi iki
// üründen bahsedildiğini hatırlar - çok turlu konuşma bağlamı için kritik.

const extractorOutput = $('Karşılaştırma Bilgisi Çıkar (AI)').first().json.output;
const secim1 = (extractorOutput.secim_1 || "").trim();
const secim2 = (extractorOutput.secim_2 || "").trim();

function parseRedisJson(nodeJson) {
  try {
    const redisValue = nodeJson.value ?? nodeJson.data ?? nodeJson.propertyName ?? nodeJson[Object.keys(nodeJson)[0]];
    const parsed = typeof redisValue === "string" ? JSON.parse(redisValue) : redisValue;
    return parsed || null;
  } catch (e) {
    return null;
  }
}

// last_products listesi (Redis1 node'undan)
let lastProducts = parseRedisJson($('Son Önerilen Ürünleri Oku').first().json);
if (!Array.isArray(lastProducts)) lastProducts = [];

function urunBul(secim) {
  if (!secim || lastProducts.length === 0) return null;
  const sayi = parseInt(secim, 10);
  if (!isNaN(sayi) && sayi >= 1 && sayi <= lastProducts.length) {
    return lastProducts[sayi - 1];
  }
  const normalizedSecim = secim.toLowerCase();
  const eslesme = lastProducts.find(p =>
    p.urun_adi.toLowerCase().includes(normalizedSecim) ||
    p.marka.toLowerCase().includes(normalizedSecim)
  );
  return eslesme || null;
}

let id1 = null, id2 = null;

if (secim1 && secim2) {
  // Bu mesajda ürün seçimi açıkça belirtilmiş
  const urun1 = urunBul(secim1);
  const urun2 = urunBul(secim2);
  if (urun1 && urun2) {
    id1 = urun1.id;
    id2 = urun2.id;
  }
} else {
  // Bu mesajda seçim yok - muhtemelen önceki soruya (kritere) cevap veriyor.
  // Redis'teki bekleyen karşılaştırma kaydına bak.
  const pending = parseRedisJson($('Bekleyen Karşılaştırmayı Oku').first().json);
  if (pending && pending.id1 && pending.id2) {
    id1 = pending.id1;
    id2 = pending.id2;
  }
}

if (!id1 || !id2) {
  return [{
    json: {
      hata: true,
      mesaj: "İki ürünü de net olarak belirleyemedim. Önce Ürün Keşif ile birkaç seçenek görmemiz, sonra 'ilk ürün ile ikincisini karşılaştır' gibi net bir ifade kullanmanız gerekiyor."
    }
  }];
}

return [{
  json: {
    hata: false,
    id1,
    id2,
    ids: `${id1},${id2}`
  }
}];

// Kriter belirtilmemiş durumda kullanılır. LLM'e bırakmadan, doğrudan ve güvenilir
// şekilde kullanıcıya soru soruyoruz - bu bir kontrol akışı kararı, LLM'in "hissine"
// bırakılmayacak kadar kritik.

const response = $('Karşılaştırma Verisini Getir (API)').first().json;

if (!response.urunler || response.urunler.length < 2) {
  return [{ json: { output: "Karşılaştırma için ürünleri bulamadım, tekrar dener misiniz?" } }];
}

const [urun1, urun2] = response.urunler;

const soru = `**${urun1.urun_adi}** ile **${urun2.urun_adi}**'ı karşılaştıralım.

Sizin için en önemli olan ne? Örneğin:
- Fiyat mı önemli, yoksa kalite/puan mı?
- Aradığınız özel bir özellik var mı? (örn: su geçirmez, uzun ömürlü, kalıcı)

Bunu söylerseniz, hangisinin size daha uygun olduğunu net şekilde gösterebilirim.`;

return [{ json: { output: soru } }];

// Karşılaştırma tablosunu kod bloğu içinde, sabit genişlikli (monospace) ve hizalı
// olarak üretir. LLM'e bırakmıyoruz çünkü karakter hizalama bir kod problemi, dil
// üretimi problemi değil - LLM'ler boşluk sayısını tutturmakta güvenilir değil.
// n8n chat paneli markdown tabloyu (|...|) render etmediği için bu yaklaşım şart.

const response = $('Karşılaştırma Verisini Getir (API)').first().json;
const [urun1, urun2] = response.urunler;

const fiyatFmt = (f) => f.toLocaleString('tr-TR', { minimumFractionDigits: 2 }) + " TL";

const satirlar = [
  ["Kriter", urun1.marka, urun2.marka],
  ["Fiyat", fiyatFmt(urun1.fiyat), fiyatFmt(urun2.fiyat)],
  ["Puan", `${urun1.puan}/5`, `${urun2.puan}/5`],
  ["Yorum", String(urun1.yorum_sayisi), String(urun2.yorum_sayisi)],
  ["Stok", urun1.stok_durumu === "STOKTA" ? "Var" : "Yok", urun2.stok_durumu === "STOKTA" ? "Var" : "Yok"],
];

// Her sütun için en uzun metne göre genişlik hesapla (hizalama için)
const col1Width = Math.max(...satirlar.map(r => r[0].length)) + 2;
const col2Width = Math.max(...satirlar.map(r => r[1].length)) + 2;
const col3Width = Math.max(...satirlar.map(r => r[2].length)) + 2;

function pad(text, width) {
  return text + " ".repeat(Math.max(0, width - text.length));
}

const tabloSatirlari = satirlar.map((r, i) => {
  const line = pad(r[0], col1Width) + pad(r[1], col2Width) + r[2];
  if (i === 0) {
    const ayirac = "-".repeat(col1Width + col2Width + col3Width);
    return line + "\n" + ayirac;
  }
  return line;
});

const asciiTablo = "**" + urun1.marka + " vs " + urun2.marka + "**\n```\n" + tabloSatirlari.join("\n") + "\n```";

// --- Özellik bazlı karşılaştırma (ikinci tablo) ---
// Her iki ürünün TÜM özelliklerini birleştirip, hangisinde hangi özellik var diye
// ✓/✗ ile gösteriyoruz. Bu tamamen gerçek veriye dayalı, deterministik bir eşleştirme
// (kullanıcının serbest metin kriterini yorumlamaya çalışmıyoruz, ürünün kendi
// özellik listesini kullanıyoruz).
const tumOzellikler = [...new Set([...(urun1.ozellikler || []), ...(urun2.ozellikler || [])])];

let ozellikTablosu = "";
if (tumOzellikler.length > 0) {
  const ozSatirlari = tumOzellikler.map(oz => {
    const has1 = (urun1.ozellikler || []).includes(oz) ? "✓" : "✗";
    const has2 = (urun2.ozellikler || []).includes(oz) ? "✓" : "✗";
    return [oz, has1, has2];
  });

  const ozCol1 = Math.max(...ozSatirlari.map(r => r[0].length), "Özellik".length) + 2;
  const ozCol2 = urun1.marka.length + 2;
  const ozCol3 = urun2.marka.length + 2;

  const ozBaslik = pad("Özellik", ozCol1) + pad(urun1.marka, ozCol2) + urun2.marka;
  const ozAyirac = "-".repeat(ozCol1 + ozCol2 + ozCol3);
  const ozSatirMetinleri = ozSatirlari.map(r => pad(r[0], ozCol1) + pad(r[1], ozCol2) + r[2]);

  ozellikTablosu = "\n\n**Özellik Karşılaştırması**\n```\n" + ozBaslik + "\n" + ozAyirac + "\n" + ozSatirMetinleri.join("\n") + "\n```";
}

const tamTablo = asciiTablo + ozellikTablosu;

return [{
  json: {
    asciiTablo: tamTablo,
    urun1_adi: urun1.urun_adi,
    urun2_adi: urun2.urun_adi
  }
}];

// Tablo ve LLM'in ürettiği anlatım metnini birleştirir. Set/Edit Fields node yerine
// Code node kullanıyoruz çünkü JS'te \n her zaman gerçek satır sonudur - n8n'in
// Set node arayüzünde bu bazen literal metin olarak kalabiliyor.

// NOT: Node ismini kendi workflow'undaki gerçek isimle değiştir (örn. 'Code in JavaScript3')
const tabloNode = $('Karşılaştırma Tablosu Oluştur').first().json;
const llmCiktisi = $input.first().json;

const anlatimMetni = llmCiktisi.text || llmCiktisi.output || "";

const nihaiMetin = tabloNode.asciiTablo + "\n\n" + anlatimMetni;

return [{ json: { output: nihaiMetin } }];

// LLM'in çıktısını (bazen ```json ile sarılmış, bazen ham) güvenli şekilde JSON'a çevirir.
// Bu, n8n'in Information Extractor node'undaki katı/kırılgan parser'ın aksine, hataya
// toleranslı - format biraz bozuk olsa bile elimizden geldiğince düzeltmeye çalışır.

const rawText = $input.first().json.text || $input.first().json.output || "";

function guvenliJsonAyristir(text) {
  // 1. Markdown kod bloğu işaretlerini temizle (```json ... ``` veya ``` ... ```)
  let temiz = text.trim();
  temiz = temiz.replace(/^```json\s*/i, "").replace(/^```\s*/, "").replace(/```\s*$/, "");
  temiz = temiz.trim();

  try {
    return JSON.parse(temiz);
  } catch (e) {
    // 2. Metin içinde bir yerde { ... } varsa onu yakalamayı dene (son çare)
    const match = temiz.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (e2) {
        return null;
      }
    }
    return null;
  }
}

const parsed = guvenliJsonAyristir(rawText);

if (!parsed) {
  // Ayrıştırma tamamen başarısız olursa güvenli varsayılan değerler döndür,
  // sistem çökmesin
  return [{
    json: {
      urun_referansi: "",
      yeni_yorum_ekleniyor_mu: "hayir",
      yeni_yorum_metni: "",
      yeni_yorum_yildiz: 0,
      kullanici_adi: "",
      yorum_siliniyor_mu: "hayir",
      silme_ipucu: "",
      uygunsuz_icerik_mi: "hayir",
      ayristirma_hatasi: true,
    }
  }];
}

return [{
  json: {
    urun_referansi: parsed.urun_referansi || "",
    yeni_yorum_ekleniyor_mu: parsed.yeni_yorum_ekleniyor_mu || "hayir",
    yeni_yorum_metni: parsed.yeni_yorum_metni || "",
    yeni_yorum_yildiz: parsed.yeni_yorum_yildiz || 0,
    kullanici_adi: parsed.kullanici_adi || "",
    yorum_siliniyor_mu: parsed.yorum_siliniyor_mu || "hayir",
    silme_ipucu: parsed.silme_ipucu || "",
    uygunsuz_icerik_mi: parsed.uygunsuz_icerik_mi || "hayir",
    ayristirma_hatasi: false,
  }
}];

// Kullanıcının "Apple", "aplle" (yazım hatalı), "1" gibi belirttiği ürün referansını
// gerçek ürün ID'sine çevirir. Yazım hatalarına karşı Levenshtein mesafesi kullanılır.
// Eğer kullanıcı bu mesajda hiç ürün belirtmediyse (örn. "yorum içeriğim şuydu" gibi kısa
// bir takip mesajı), en son konuşulan ürünü Redis'ten hatırlar - kullanıcı her seferinde
// ürün adını tekrar yazmak zorunda kalmasın diye.

// ÖNEMLİ: Bu node'un doğrudan girişi artık "son aktif ürün" Redis node'u. last_products
// listesine ayrıca isimle referans veriyoruz. Node isimlerini kendi workflow'una göre uyarla.
const extractorOutput = $('JSON Güvenli Ayrıştır1').first().json;
const referans = (extractorOutput.urun_referansi || "").trim();

function parseRedisJson(nodeJson) {
  try {
    const redisValue = nodeJson.value ?? nodeJson.data ?? nodeJson.propertyName ?? nodeJson[Object.keys(nodeJson)[0]];
    if (typeof redisValue !== "string") return redisValue || null;
    try {
      return JSON.parse(redisValue);
    } catch (e) {
      // JSON değilse, düz bir string olabilir (örn. sadece "P0743" gibi bir ürün ID'si)
      return redisValue;
    }
  } catch (e) {
    return null;
  }
}

let lastProducts = parseRedisJson($('Son Önerilen Ürünleri Oku1').first().json);
if (!Array.isArray(lastProducts)) lastProducts = [];

// Bu node'un doğrudan girişi "son aktif ürün" Redis node'u
const sonAktifUrunId = parseRedisJson($input.first().json);

// --- Levenshtein mesafesi: yazım hatalarına tolerans için ---
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}

function benzerMi(a, b, esik = 2) {
  return levenshtein(a, b) <= esik;
}

function urunBul(ref) {
  if (!ref || lastProducts.length === 0) return null;

  const sayi = parseInt(ref, 10);
  if (!isNaN(sayi) && sayi >= 1 && sayi <= lastProducts.length) {
    return lastProducts[sayi - 1];
  }

  const normalizedRef = ref.toLowerCase();

  // 1. Önce tam/kısmi eşleşme dene (hızlı ve kesin)
  let eslesme = lastProducts.find(p =>
    p.urun_adi.toLowerCase().includes(normalizedRef) ||
    p.marka.toLowerCase().includes(normalizedRef)
  );
  if (eslesme) return eslesme;

  // 2. Bulamazsa, yazım hatası olabilir - marka adına Levenshtein mesafesiyle bak
  eslesme = lastProducts.find(p => benzerMi(normalizedRef, p.marka.toLowerCase()));
  return eslesme || null;
}

let urun = urunBul(referans);

// Bu mesajda ürün belirtilmemişse (referans boş), en son konuşulan ürünü hatırla
if (!urun && !referans && sonAktifUrunId) {
  urun = lastProducts.find(p => p.id === sonAktifUrunId) || null;
  if (!urun) {
    // last_products'ta yoksa bile, en azından ID'yi biliyoruz - minimal bir obje kur
    urun = { id: sonAktifUrunId, urun_adi: extractorOutput.urun_referansi || "ürün" };
  }
}

if (!urun) {
  return [{
    json: {
      hata: true,
      mesaj: "Hangi ürünü kastettiğinizi anlayamadım. Ürünün adını belirtebilir misiniz? (örn: 'Apple hakkındaki yorumları göster')"
    }
  }];
}

// --- Ekleme dalına özel kontroller (silme işlemini ASLA etkilemez) ---
if (extractorOutput.yeni_yorum_ekleniyor_mu === "evet") {
  if (extractorOutput.uygunsuz_icerik_mi === "evet") {
    return [{
      json: {
        hata: true,
        urun_id: urun.id,
        mesaj: "Bu yorumu yayınlayamıyorum çünkü uygunsuz/saygısız bir dil içeriyor gibi görünüyor. Deneyiminizi daha yapıcı bir dille ifade ederseniz memnuniyetle ekleyebilirim."
      }
    }];
  }
  if (!extractorOutput.yeni_yorum_metni || !extractorOutput.yeni_yorum_metni.trim()) {
    return [{
      json: {
        hata: true,
        urun_id: urun.id,
        mesaj: `${urun.urun_adi} için yorum eklemek istediğinizi anladım, ama ne yazmak istediğinizi tam anlayamadım. Yorumunuzu tırnak içinde belirtir misiniz? Örnek: "Ürün gerçekten kaliteli, tavsiye ederim" gibi.`
      }
    }];
  }
}

// --- KVKK: Kullanıcının tam adını gizlilik için maskele (örn. 'Nidanur Sığırta' -> 'Nidanur S.') ---
function adiMaskele(tamAd) {
  if (!tamAd) return "";
  const parcalar = tamAd.trim().split(/\s+/);
  if (parcalar.length === 1) return parcalar[0];
  const ad = parcalar[0];
  const soyadBasHarfi = parcalar[parcalar.length - 1][0];
  return `${ad} ${soyadBasHarfi}.`;
}

return [{
  json: {
    hata: false,
    urun_id: urun.id,
    urun_adi: urun.urun_adi,
    yeni_yorum_ekleniyor_mu: extractorOutput.yeni_yorum_ekleniyor_mu,
    yeni_yorum_metni: extractorOutput.yeni_yorum_metni,
    yeni_yorum_yildiz: extractorOutput.yeni_yorum_yildiz,
    kullanici_adi: adiMaskele(extractorOutput.kullanici_adi),
    yorum_siliniyor_mu: extractorOutput.yorum_siliniyor_mu,
    silme_ipucu: extractorOutput.silme_ipucu,
    uygunsuz_icerik_mi: extractorOutput.uygunsuz_icerik_mi,
  }
}];

// Code in JavaScript6'nın (ürün ID çözme) çıktısına bakar. Eğer ürün bulunamadıysa VEYA
// içerik uygunsuzsa, kullanıcıya nazik bir mesaj gösterip akışı burada durdurur -
// downstream node'ların undefined urun_id ile çökmesini önler.

const data = $input.first().json;

if (data.hata) {
  return [{ json: { output: data.mesaj } }];
}

if (data.uygunsuz_icerik_mi === "evet") {
  return [{
    json: {
      output: "Bu yorumu yayınlayamıyorum çünkü uygunsuz/saygısız bir dil içeriyor gibi görünüyor. Deneyiminizi daha yapıcı bir dille ifade ederseniz memnuniyetle ekleyebilirim."
    }
  }];
}

return [{ json: { output: "Bir sorun oluştu, tekrar dener misiniz?" } }];

// Silinecek yorumu bulur - session hafızasına DEĞİL, gerçek yorum içeriğine bakar.
// Bu sayede kullanıcı farklı bir oturumda/günde bile "harika bir ürün diye yazdığım
// yorumu sil" dediğinde doğru yorumu bulabiliriz.

const reviewsResponse = $input.first().json; // GET /reviews cevabı
const meta = $('Ürün ID Çöz + İçerik Kontrolü').first().json; // urun_id, silme_ipucu, urun_adi
const ipucu = (meta.silme_ipucu || "").trim();

function normalize(s) {
  return (s || "").toLowerCase()
    .replace(/ı/g, "i").replace(/ş/g, "s").replace(/ç/g, "c")
    .replace(/ğ/g, "g").replace(/ö/g, "o").replace(/ü/g, "u");
}

// Sadece kullanıcı tarafından eklenmiş (statik/seed olmayan) yorumlar silinebilir
const kullaniciYorumlari = (reviewsResponse.yorumlar || []).filter(y => y.kaynak === "kullanici");

let hedef = null;

if (ipucu) {
  const ipucuNorm = normalize(ipucu);
  hedef = kullaniciYorumlari.find(y =>
    normalize(y.metin).includes(ipucuNorm) || normalize(y.yazar).includes(ipucuNorm)
  );
}

// İpucu yoksa veya eşleşme bulunamadıysa: eğer kullanıcının bu üründe TEK bir yorumu
// varsa, belirsizlik olmadığı için onu sil
if (!hedef && kullaniciYorumlari.length === 1) {
  hedef = kullaniciYorumlari[0];
}

if (!hedef) {
  const mesaj = kullaniciYorumlari.length > 1
    ? "Bu üründe birden fazla yorumunuz var, hangisini kastettiğinizi anlayamadım. Yorumun içeriğinden bir kısmını belirtebilir misiniz?"
    : "Silinecek bir yorumunuzu bulamadım. Bu ürüne daha önce bir yorum yapmamış olabilirsiniz.";
  return [{ json: { hata: true, mesaj } }];
}

return [{
  json: {
    hata: false,
    urun_id: meta.urun_id,
    review_id: hedef.review_id,
  }
}];

const response = $input.first().json;

const mesaj = response.basarili
  ? "Yorumunuz başarıyla silindi."
  : "Yorumunuzu silerken bir sorun oluştu. Sadece kendi eklediğiniz yorumları silebilirsiniz.";

return [{ json: { output: mesaj } }];

// ÖNEMLİ: Redis Set node'u araya girdiği için $input artık Redis'in cevabı oluyor,
// POST isteğinin gerçek cevabına ($('Yorumu Ekle (API)')) isimle referans veriyoruz.
// 'HTTP Request2' kısmını kendi workflow'undaki gerçek POST node isminle değiştir.
const response = $('Yorumu Ekle (API)').first().json;
const urunAdi = $('Ürün ID Çöz + İçerik Kontrolü').first().json.urun_adi;

const mesaj = response.basarili
  ? `Teşekkürler! **${urunAdi}** için yorumunuz eklendi:\n\n"${response.yorum.metin}" (${response.yorum.yildiz}⭐)`
  : "Yorumunuzu eklerken bir sorun oluştu, tekrar deneyebilir misiniz?";

return [{ json: { output: mesaj } }];

// Gerçek yorumları LLM'e özetletmeden, AYNEN alt alta listeler. Sentiment analizi
// ayrı bir adımda, sadece genel değerlendirme paragrafı olarak eklenecek.

const response = $input.first().json;
const urunAdi = $('Ürün ID Çöz + İçerik Kontrolü').first().json.urun_adi;
const yorumlar = response.yorumlar || [];

if (yorumlar.length === 0) {
  return [{ json: { output: `**${urunAdi}** için henüz yorum yapılmamış.` } }];
}

const ortalama = response.ortalama_yildiz_yazili_yorumlardan;

const yildizGoster = (n) => "⭐".repeat(n) + "☆".repeat(5 - n);

const yorumSatirlari = yorumlar.map((y, i) => {
  return `**${i + 1}. ${y.yazar}** — ${yildizGoster(y.yildiz)} (${y.yildiz}/5)\n"${y.metin}"`;
}).join("\n\n");

const baslik = `**${urunAdi}** — ${yorumlar.length} yorum (ortalama ${ortalama}/5)\n\n`;

return [{
  json: {
    yorumListesi: baslik + yorumSatirlari,
    yorumlar_json: JSON.stringify(yorumlar),
  }
}];

// Deterministik yorum listesini (build-reviews-list.js çıktısı) ve LLM'in ürettiği
// genel değerlendirme paragrafını birleştirir.

// Not: 'Code in JavaScript' kısmını, senin workflow'undaki yorum listesi node'unun
// gerçek ismiyle değiştir.
const yorumListesi = $('Yorum Listesini Oluştur').first().json.yorumListesi;
const llmCiktisi = $input.first().json;
const genelDegerlendirme = llmCiktisi.text || llmCiktisi.output || "";

const nihaiMetin = yorumListesi + "\n\n---\n\n**💬 Genel Değerlendirme:**\n" + genelDegerlendirme;

return [{ json: { output: nihaiMetin } }];

// Kullanıcının HAM mesajını doğrudan tarayıp, içinde geçen bir ürün/marka adını bulur.
// Ayrı bir LLM çıkarma adımına gerek yok - bu basit bir metin arama görevi, LLM'in JSON
// formatlama hatası yapma riski olmadan, daha hızlı ve güvenilir çalışır.

const chatInput = $('When chat message received').item.json.chatInput || "";

function parseRedisJson(nodeJson) {
  try {
    const redisValue = nodeJson.value ?? nodeJson.data ?? nodeJson.propertyName ?? nodeJson[Object.keys(nodeJson)[0]];
    if (typeof redisValue !== "string") return redisValue || null;
    try { return JSON.parse(redisValue); } catch (e) { return redisValue; }
  } catch (e) {
    return null;
  }
}

// Bu node'un doğrudan girişi Redis (last_products) olmalı
let lastProducts = parseRedisJson($input.first().json);
if (!Array.isArray(lastProducts)) lastProducts = [];

function normalize(s) {
  return (s || "").toLowerCase()
    .replace(/ı/g, "i").replace(/ş/g, "s").replace(/ç/g, "c")
    .replace(/ğ/g, "g").replace(/ö/g, "o").replace(/ü/g, "u");
}

const mesajNorm = normalize(chatInput);

// Listedeki her ürün için, markası veya adının bir kısmı mesajda geçiyor mu diye bak
let bulunanUrun = null;
for (const p of lastProducts) {
  const markaNorm = normalize(p.marka);
  const adiKelimeleri = normalize(p.urun_adi).split(/\s+/).filter(w => w.length >= 4);
  if (mesajNorm.includes(markaNorm) && adiKelimeleri.some(k => mesajNorm.includes(k))) {
    bulunanUrun = p;
    break;
  }
}
// Marka eşleşip tam ürün ismi eşleşmezse bile, sadece marka + "kaç tane var/stok" gibi
// bir bağlamda tek adaysa onu kullan
if (!bulunanUrun) {
  const markaEslesenler = lastProducts.filter(p => mesajNorm.includes(normalize(p.marka)));
  if (markaEslesenler.length === 1) bulunanUrun = markaEslesenler[0];
}

return [{
  json: {
    urun_belirtildi_mi: !!bulunanUrun,
    urun_id: bulunanUrun ? bulunanUrun.id : null,
    urun_adi: bulunanUrun ? bulunanUrun.urun_adi : null,
  }
}];

const urun = $input.first().json;
const metin = `${urun.urun_adi} (${urun.marka}) - Stok Durumu: ${urun.stok_durumu === "STOKTA" ? `Stokta (${urun.stok} adet)` : "Stokta Yok"}, Fiyat: ${urun.fiyat} TL`;
return [{ json: { urunVerisi: metin } }];

// Kullanıcının yüklediği görseli, OpenAI Vision API'sinin beklediği base64 data URI
// formatına çevirir. n8n'de binary veri genelde 'data' anahtarı altında gelir.

const binaryKeys = Object.keys($input.first().binary || {});
if (binaryKeys.length === 0) {
  return [{ json: { hata: true, mesaj: "Görsel bulunamadı." } }];
}

const binaryKey = binaryKeys[0];
const binaryData = $input.first().binary[binaryKey];
const mimeType = binaryData.mimeType || "image/jpeg";

// n8n'de binary buffer'a erişim - helper fonksiyon kullanıyoruz
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString("base64");
const dataUri = `data:${mimeType};base64,${base64}`;

return [{ json: { imageDataUri: dataUri, hata: false } }];

