// OpenAI Chat Completions API'sinin ham cevabından, modelin ürettiği metni çıkarıp
// JSON olarak ayrıştırır. Diğer modüllerdeki savunmacı ayrıştırma mantığıyla aynı.

const response = $input.first().json;
const rawText = response.choices && response.choices[0] && response.choices[0].message
  ? response.choices[0].message.content
  : "";

function guvenliJsonAyristir(text) {
  let temiz = (text || "").trim();
  temiz = temiz.replace(/^```json\s*/i, "").replace(/^```\s*/, "").replace(/```\s*$/, "");
  temiz = temiz.trim();
  try {
    return JSON.parse(temiz);
  } catch (e) {
    const match = temiz.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { return null; }
    }
    return null;
  }
}

const parsed = guvenliJsonAyristir(rawText);

if (!parsed) {
  return [{
    json: {
      hata: true,
      mesaj: "Görseli analiz edemedim, tekrar deneyebilir misiniz? Farklı bir açıdan çekilmiş bir fotoğraf işe yarayabilir."
    }
  }];
}

return [{
  json: {
    hata: false,
    urun_tipi: parsed.urun_tipi || "",
    renk: parsed.renk || "",
    arama_terimi: parsed.arama_terimi || "",
    tahmini_kategori: parsed.tahmini_kategori || "",
  }
}];

// Görsel aramadan gelen ürün sonuçlarını, Ürün Keşif modülündeki kart formatına benzer
// şekilde gösterir, ama görsel analizinden ne anlaşıldığını da başta belirtir.
// Not: '$('Code in JavaScript')' kısmını, vision sonucunu ayrıştıran node'un GERÇEK
// ismiyle değiştir.

const response = $input.first().json;
const analiz = $('Code in JavaScript1').first().json;
const oneriler = response.oneriler || response.urunler || [];

if (oneriler.length === 0) {
  return [{
    json: {
      output: `Görselinizde **${analiz.urun_tipi || "bir ürün"}** (${analiz.renk || "renk belirsiz"}) tespit ettim, ama kataloğumuzda eşleşen bir ürün bulamadım. Farklı bir arama terimiyle tekrar dener misiniz?`
    }
  }];
}

const kategoriEmoji = {
  "Elektronik": "🔌", "Kadın": "👗", "Erkek": "👔", "Kozmetik": "💄",
  "Ayakkabı & Çanta": "👜", "Ev & Yaşam": "🏠", "Spor & Outdoor": "⚽",
  "Anne & Çocuk": "🧸", "Süpermarket": "🛒", "Saat & Aksesuar": "⌚"
};

const kartlar = oneriler.slice(0, 5).map((urun, index) => {
  const emoji = urun.alt_kategori === "Elektronik" ? "🔌" : (kategoriEmoji[urun.ana_kategori] || "🛍️");
  const fiyatFormatli = urun.fiyat.toLocaleString('tr-TR', { minimumFractionDigits: 2 });
  const stokMetni = urun.stok_durumu === "STOKTA" ? "✅ Stokta" : "❌ Stokta yok";

  return `**${index + 1}. ${emoji} ${urun.urun_adi}**

- Marka: ${urun.marka}
- Fiyat: **${fiyatFormatli} TL**
- Puan: ⭐ ${urun.puan}/5 (${urun.yorum_sayisi} değerlendirme)
- Durum: ${stokMetni}`;
}).join("\n\n———————————————\n\n");

const baslik = `📸 Görselinizi analiz ettim: **${analiz.urun_tipi}** (${analiz.renk}) gibi görünüyor.\n\nBuna en yakın ${oneriler.length} ürünü buldum:\n\n`;

return [{ json: { output: baslik + kartlar } }];
